# frozen_string_literal: true

module Investing
  module Allocation
    # Turns Calculator output into a rebalance verdict + deterministic,
    # human-readable drift report (TDD §7.2). Pure — no I/O.
    #
    # rebalance_required? is true when ANY group leaves its band OR any
    # sleeve drifts at/over threshold_to_act_pct. The narrative is a
    # deterministic template (same inputs -> same string), test-pinned by
    # A-ALC-06 — it is NOT generated by an LLM (TDD §19.4).
    class DriftAnalyzer < ApplicationService
      Trigger = Data.define(:kind, :key, :actual_pct, :target_pct, :drift_pct,
                            :band_lower_pct, :band_upper_pct)
      DriftReport = Data.define(:rebalance_required, :triggers, :overweights,
                                :underweights, :max_abs_drift_pp, :narrative) do
        def rebalance_required? = rebalance_required
      end

      def initialize(calculations:, policy:)
        super()
        @calculations = calculations
        @policy = policy
      end

      def call
        triggers = group_triggers + sleeve_triggers
        overweights = sorted_by_drift(positive: true)
        underweights = sorted_by_drift(positive: false)
        DriftReport.new(
          rebalance_required: triggers.any?,
          triggers: triggers,
          overweights: overweights,
          underweights: underweights,
          max_abs_drift_pp: max_abs_drift,
          narrative: narrative(triggers, overweights, underweights)
        )
      end

      private

      def group_triggers
        @calculations.groups.reject(&:within_band).map do |group|
          Trigger.new(
            kind: :group_band_breach, key: group.group_key,
            actual_pct: group.actual_pct, target_pct: group.target_pct,
            drift_pct: group.drift_pct,
            band_lower_pct: group.band_lower_pct, band_upper_pct: group.band_upper_pct
          )
        end
      end

      def sleeve_triggers
        threshold = @policy.threshold_to_act_pct
        @calculations.sleeves.select { |s| s.drift_pct.abs >= threshold }.map do |sleeve|
          Trigger.new(
            kind: :sleeve_threshold, key: sleeve.sleeve_key,
            actual_pct: sleeve.actual_pct, target_pct: sleeve.target_pct,
            drift_pct: sleeve.drift_pct,
            band_lower_pct: sleeve.band_lower_pct, band_upper_pct: sleeve.band_upper_pct
          )
        end
      end

      # Sorted by |drift_value| descending, display-order as tiebreaker —
      # deterministic output for identical inputs (A-ALC-06).
      def sorted_by_drift(positive:)
        sleeves = @calculations.sleeves.select do |s|
          positive ? s.drift_value.positive? : s.drift_value.negative?
        end
        sleeves.sort_by { |s| [-s.drift_value.abs, index_of(s.sleeve_key)] }
      end

      def index_of(sleeve_key)
        @calculations.sleeves.index { |s| s.sleeve_key == sleeve_key } ||
          @calculations.sleeves.size
      end

      def max_abs_drift
        @calculations.sleeves.map { |s| s.drift_pct.abs }.max || BigDecimal("0")
      end

      def narrative(triggers, overweights, underweights)
        return "PORTFOLIO IN BALANCE — no band breach, all sleeve drifts below threshold." if triggers.empty?

        <<~TEXT
          PORTFOLIO REBALANCE REQUIRED

          Portfolio Value: #{money(@calculations.total_value)}

          Group allocation vs policy bands:
          #{@calculations.groups.map { |g| group_line(g) }.join("\n")}

          Largest overweights: #{sleeves_summary(overweights)}
          Largest underweights: #{sleeves_summary(underweights)}
        TEXT
      end

      def group_line(group)
        band = "#{fmt(group.band_lower_pct)}–#{fmt(group.band_upper_pct)}%" if group.band_lower_pct
        state = group.within_band ? "OK" : "BREACHED"
        "#{group.group_key.humanize}: target #{fmt(group.target_pct)}%, " \
          "actual #{fmt(group.actual_pct)}%, drift #{signed(group.drift_pct)}pp" \
          "#{", band #{band}" if band} — #{state}"
      end

      def sleeves_summary(sleeves)
        sleeves.first(3).map do |sleeve|
          "#{sleeve.sleeve_key.humanize} #{signed(sleeve.drift_pct)}pp (#{money(sleeve.drift_value)})"
        end.join(", ").presence || "none"
      end

      def signed(value)
        value.negative? ? fmt(value) : "+#{fmt(value)}"
      end

      def fmt(value)
        format("%.1f", value)
      end

      # BigDecimal#format is private; plain to_s("F") keeps the narrative
      # deterministic without locale formatting.
      def money(value)
        value.to_s("F")
      end
    end
  end
end
